const symbols=['◯','✚','≋','□','☆'];
const symbolNames=['Circle','Cruz','Ondas','Cuadrado','Estrella'];
function pmDay(){const d=new Date();return `${d.getFullYear()}-${d.getMonth()+1}-${d.getDate()}`}
function pmLoad(k){try{const r=JSON.parse(localStorage.getItem('pm-daily-'+k)||'null');return r&&r.day===pmDay()?r:null}catch{return null}}
function pmSave(k,o){try{localStorage.setItem('pm-daily-'+k,JSON.stringify({day:pmDay(),...o}))}catch{}}
function pmLeft(){const n=new Date(),m=new Date(n.getFullYear(),n.getMonth(),n.getDate()+1),t=Math.ceil((m-n)/60000);return `${Math.floor(t/60)} h ${t%60} min`}
function esp(){const sv=pmLoad('esp');if(sv){state.espHits=sv.hits;state.espHistory=sv.history;state.espSaved=sv.td;espResult();return}state.espSaved=null;state.espRound=0;state.espHits=0;state.espHistory=[];state.espTarget=Math.floor(Math.random()*symbols.length);renderEspRound()}
function espGuide(){return `<div class="esp-guide"><div class="esp-guide-title"><span>✦</span><div><b>How does it work?</b><small>A short experiment to listen to your first impression.</small></div></div><div class="esp-steps"><div><b>1</b><span><strong>Close your eyes</strong><small>Breathe and look away from the symbols.</small></span></div><div><b>2</b><span><strong>Imagine a shape</strong><small>With your eyes closed, think of the one you feel.</small></span></div><div><b>3</b><span><strong>Open and choose</strong><small>Tap that option; then the card is revealed.</small></span></div></div><p class="esp-expectation"><b>Important:</b> there are 5 symbols, so getting it right by chance is also possible. You don’t need to “have powers” or look for a perfect answer.</p></div>`}
function renderEspRound(){shell(`${head('✦','Extrasensory Perception','Close your eyes, imagine a symbol, and then check your choice.')}<div class="panel esp-panel">${espGuide()}<div class="esp-progress"><i style="width:${state.espRound/5*100}%"></i></div><div class="esp-status"><span>ROUND ${state.espRound+1} OF 5</span><b>Hits: ${state.espHits}</b></div><div class="esp-target-card"><span>✦ HIDDEN CARD</span><div class="score-orb">?</div><p>The card has already been chosen at random. Close your eyes before you choose: it won’t change while you decide.</p></div><div class="zener">${symbols.map((s,i)=>`<button class="choice symbol" data-symbol="${i}" aria-label="Choose ${symbolNames[i]}"><span>${s}</span><small>${symbolNames[i]}</small></button>`).join('')}</div><p class="esp-prompt">Once you’ve imagined your symbol with your eyes closed, open them and tap an option.</p><div id="espFeedback" aria-live="polite"></div></div>`);document.querySelectorAll('[data-symbol]').forEach(b=>b.onclick=()=>{const target=state.espTarget,choice=+b.dataset.symbol,hit=choice===target;if(hit)state.espHits++;state.espHistory.push({choice,target,hit});sound(hit?'reveal':'tap');document.querySelectorAll('[data-symbol]').forEach(x=>x.disabled=true);b.classList.add('selected');document.querySelector(`[data-symbol="${target}"]`)?.classList.add('target');$('.score-orb').textContent=symbols[target];$('#espFeedback').innerHTML=`<div class="esp-feedback ${hit?'hit':'miss'}"><div class="esp-reveal-label">${hit?'✦ MATCH!':'The card is revealed'}</div><strong>${hit?'Your first impression matched':'This time it was a different sign'}</strong><div class="esp-comparison"><span>Your choice<b>${symbols[choice]} ${symbolNames[choice]}</b></span><i>VS</i><span>Hidden card<b>${symbols[target]} ${symbolNames[target]}</b></span></div><p>${hit?'That’s one hit. Notice how you felt before choosing.':'No worries: each round is independent and chance is part of the game.'}</p><button class="primary" id="nextEsp">${state.espRound===4?'See my reading':'Next round'}</button></div>`;$('#nextEsp').onclick=()=>{sound();state.espRound++;if(state.espRound>=5)espResult();else{state.espTarget=Math.floor(Math.random()*symbols.length);renderEspRound()}}});}
function espLongestStreak(history){let best=0,current=0;for(const round of history){if(round.hit){current++;best=Math.max(best,current)}else current=0}return best}
const espTierContent={
  5:[['Perfect streak','You got all 5 rounds right. Statistically, the probability of doing that by chance alone is just 1 in 3,125 — something real happened in your attention this time, though a single session is never enough to draw firm conclusions.'],
     ['Chance almost never does this','5 out of 5 is a result that pure chance very rarely produces. It’s worth taking the test again another day, in a different mood, to see whether the pattern repeats.']],
  4:[['A notable streak','4 out of 5 hits is far above what chance produces on average (which would be 1 out of 5). Pay attention to what you were doing differently right before getting it right.'],
     ['Beyond coincidence','Getting 4 out of 5 right, by pure chance, happens less than 1% of the time. It’s not proof of anything paranormal, but it does invite you to repeat the experiment with curiosity.']],
  3:[['Radiant intuition','In this session you gathered several matches above the expected average (1 in 5 by chance). Take it as an invitation to pay attention to your hunches, not as definitive proof.'],
     ['A streak that catches the eye','3 hits is more than triple what pure chance predicts. See if there was a pattern: did you do better at the start, at the end, with a particular symbol?']],
  2:[['Somewhat above average','You got 2 out of 5: a little above the average for chance, something that happens in about 20% of sessions. Pausing and playing without pressure help you notice how you decide.'],
     ['A result within the expected range','2 out of 5 is close to what statistics predict for anyone playing at random — but that doesn’t take away from how interesting the experience is.']],
  1:[['One hit, as expected','Getting 1 out of 5 is exactly what chance gives on average. Playing calmly and without pressure helps you notice how you decide, even if it doesn’t change the odds.'],
     ['Right on average','1 out of 5 is exactly what probability predicts if you chose at random each round — a perfectly normal and expected result.']],
  0:[['Explorer mind','Chance prevailed today, and that’s also part of the experiment. One short session doesn’t define your intuition or your ability to perceive.'],
     ['Zero isn’t a bad result','Missing all 5 rounds happens to about a third of people who play at random (around 33%): it’s a very common result. It says nothing bad about your intuition.']]
};
function espResult(){
  const [title,desc]=state.espSaved||espTierContent[state.espHits][Math.floor(Math.random()*espTierContent[state.espHits].length)];
  if(!state.espSaved){state.espSaved=[title,desc];pmSave('esp',{hits:state.espHits,history:state.espHistory,td:[title,desc]})}
  const streak=espLongestStreak(state.espHistory);
  const recap=state.espHistory.map((r,i)=>`<div class="esp-recap-row ${r.hit?'hit':'miss'}"><span>Round ${i+1}</span><span>${symbols[r.choice]} ${symbolNames[r.choice]}</span><span>${r.hit?'✓ hit':`✗ era ${symbols[r.target]} ${symbolNames[r.target]}`}</span></div>`).join('');
  shell(`${head('✦','Your intuitive reading','Here’s how this little experiment ended')}<div class="panel esp-result-panel"><div class="score-orb">${state.espHits}/5</div><div class="result"><strong>${title}</strong><p>${desc}</p></div>${streak>=2?`<div class="esp-score-guide"><h3>✦ Tu mejor racha</h3><div><b>${streak} ${streak===1?'streak of hits':'hits in a row'}</b><span>${streak>=3?'A streak this long is uncommon by pure chance — it was the strongest moment of your session.':'Two hits in a row is already a bit more than typical by chance.'}</span></div></div>`:''}<div class="esp-score-guide"><h3>Round by round</h3>${recap}</div><div class="esp-score-guide"><h3>How to read your score</h3><div><b>0 of 5</b><span>It sounds like bad luck, but it’s a very common result: missing all 5 rounds by pure chance happens about 33% of the time (1 in 3). <b>Your perception in this session:</b> a session of just 5 rounds is far too short to say anything about your intuition; if you’re curious, repeat the experiment another day.</span></div><div><b>1 of 5</b><span>It’s the average result you’d expect even when choosing at random (20% probability per round). <b>Your perception in this session:</b> stayed in a neutral state, neither especially awake nor blocked—your usual starting point.</span></div><div><b>2 of 5</b><span>A session with a few matches, something that happens by chance about 20% of the time. <b>Your perception in this session:</b> had moments where your first impression matched the hidden card—a sign that, at least at times, you were well attuned.</span></div><div><b>3 of 5</b><span>A striking streak: it happens by chance about 5% of the time (1 in 20). <b>Your perception in this session:</b> was more active than usual—it’s worth noticing what state of mind you were in right before you started playing.</span></div><div><b>4 of 5</b><span>This happens by pure chance less than 1% of the time. <b>Your perception in this session:</b> was at a very high point of attunement with your first instinct, whether by coincidence or a good moment of connection with yourself.</span></div><div><b>5 of 5</b><span>The probability of getting this by chance alone is 1 in 3,125—rarer than flipping 11 heads in a row. <b>Your perception in this session:</b> was in perfect harmony between your first impression and reality, the kind of moment that reminds you how present you can be when you trust your instinct without overthinking it.</span></div></div><div class="esp-score-guide"><h3>✦ The origin of this game</h3><div><span>This format is inspired by the Zener cards, created in the 1930s by psychologist Karl Zener and used by J.B. Rhine at Duke University to study extrasensory perception. With 5 possible symbols, pure chance predicts one hit in every five attempts—modern science has found no reproducible evidence of real extrasensory perception in these experiments, but they remain an entertaining game for observing your own intuition.</span></div></div><button class="primary" id="again">Repeat the test</button><p class="note">This game is for recreation: it does not scientifically measure extrasensory abilities or predict decisions or events.</p></div>`);
  sound('reveal');log('esp_complete',{hits:state.espHits,streak});
  const ag=$('#again');if(ag){const note=document.createElement('p');note.className='note';note.style.textAlign='center';note.innerHTML=`✦ Today’s experiment is already done: repeating it several times in the same day only mixes in chance. You’ll be able to do a new one in <b>${pmLeft()}</b>.`;ag.replaceWith(note)}
}

