(function(){var id=(window.__PM_START||'');if(!id||!/^[\w-]+$/.test(id))return;var n=0;(function go(){var b=document.querySelector('.tool-card[data-tool="%s"]'.replace('%s',id));if(b){b.click();setTimeout(function(){try{if(document.activeElement&&document.activeElement.blur)document.activeElement.blur();window.scrollTo(0,0);if(window.parent!==window)window.parent.scrollTo(0,0);}catch(e){}},350);return;}if(++n<50)setTimeout(go,100);})();})();
